/**
 * xrpldashboard site search — client-side, no external dependencies.
 *
 * Index is /static/search-index.json (generated by scripts/build_search_index.py
 * at deploy time). Loaded once on first open, then cached in memory.
 *
 * Keyboard: Cmd/Ctrl+K to open, Esc to close, ↑↓ to navigate, Enter to follow.
 */

(function () {
  "use strict";

  var INDEX_URL = "/static/search-index.json";
  var MAX_RESULTS = 8;

  var overlay, input, resultsList, statusEl;
  var indexData = null;
  var loadPromise = null;
  var activeIdx = -1;

  // ── DOM bootstrap ────────────────────────────────────────────────────────

  function mount() {
    if (document.getElementById("xd-search-overlay")) return;

    var el = document.createElement("div");
    el.id = "xd-search-overlay";
    el.setAttribute("role", "dialog");
    el.setAttribute("aria-modal", "true");
    el.setAttribute("aria-label", "Site search");
    el.innerHTML = [
      '<div id="xd-search-box">',
      '  <div id="xd-search-input-row">',
      '    <svg id="xd-search-icon" viewBox="0 0 20 20" fill="none"',
      '         stroke="currentColor" stroke-width="2" width="18" height="18"',
      '         aria-hidden="true">',
      '      <circle cx="8.5" cy="8.5" r="5.5"/>',
      '      <line x1="13" y1="13" x2="18" y2="18"/>',
      '    </svg>',
      '    <input id="xd-search-input" type="search"',
      '           placeholder="Search pages, terms, and claims\u2026"',
      '           autocomplete="off" spellcheck="false" aria-autocomplete="list"',
      '           aria-controls="xd-search-results"/>',
      '    <kbd id="xd-search-esc">esc</kbd>',
      '  </div>',
      '  <div id="xd-search-status" aria-live="polite" aria-atomic="true"></div>',
      '  <ul id="xd-search-results" role="listbox"></ul>',
      '  <div id="xd-search-footer">',
      '    Search covers pages, definitions, and claims \u2014',
      '    for live data questions, use the tools on each page.',
      '  </div>',
      '</div>',
    ].join("");
    document.body.appendChild(el);

    overlay = el;
    input = document.getElementById("xd-search-input");
    resultsList = document.getElementById("xd-search-results");
    statusEl = document.getElementById("xd-search-status");

    overlay.addEventListener("click", function (e) {
      if (e.target === overlay) close();
    });
    input.addEventListener("input", onInput);
    input.addEventListener("keydown", onInputKey);
    document.getElementById("xd-search-esc").addEventListener("click", close);
  }

  // ── Index loading ────────────────────────────────────────────────────────

  function loadIndex() {
    if (indexData) return Promise.resolve(indexData);
    if (loadPromise) return loadPromise;
    loadPromise = fetch(INDEX_URL)
      .then(function (r) {
        if (!r.ok) throw new Error("search index fetch failed: " + r.status);
        return r.json();
      })
      .then(function (data) {
        indexData = data;
        return data;
      });
    return loadPromise;
  }

  // ── Search logic ─────────────────────────────────────────────────────────

  function tokenize(s) {
    return s
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, " ")
      .split(/\s+/)
      .filter(Boolean);
  }

  function score(entry, tokens) {
    var titleLow = (entry.title || "").toLowerCase();
    var bodyLow = (entry.body || "").toLowerCase();
    var total = 0;
    for (var i = 0; i < tokens.length; i++) {
      var t = tokens[i];
      if (titleLow.indexOf(t) !== -1) total += 3;
      if (bodyLow.indexOf(t) !== -1) total += 1;
    }
    // Exact title-prefix bonus
    if (titleLow.startsWith(tokens[0])) total += 2;
    return total;
  }

  function search(query) {
    if (!indexData) return [];
    var tokens = tokenize(query);
    if (!tokens.length) return [];
    var scored = [];
    for (var i = 0; i < indexData.length; i++) {
      var s = score(indexData[i], tokens);
      if (s > 0) scored.push({ entry: indexData[i], score: s });
    }
    scored.sort(function (a, b) { return b.score - a.score; });
    return scored.slice(0, MAX_RESULTS).map(function (x) { return x.entry; });
  }

  // ── Rendering ────────────────────────────────────────────────────────────

  var TYPE_LABELS = {
    page: "page",
    section: "section",
    term: "term",
    claim: "claim",
  };

  function escape(s) {
    return (s || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function excerpt(body, tokens) {
    if (!body) return "";
    var low = body.toLowerCase();
    var start = 0;
    for (var i = 0; i < tokens.length; i++) {
      var pos = low.indexOf(tokens[i]);
      if (pos !== -1) { start = Math.max(0, pos - 40); break; }
    }
    var snip = body.slice(start, start + 120);
    if (start > 0) snip = "\u2026" + snip;
    if (start + 120 < body.length) snip += "\u2026";
    return snip;
  }

  function renderResults(results, tokens) {
    resultsList.innerHTML = "";
    activeIdx = -1;
    if (!results.length) {
      statusEl.textContent = "No results.";
      return;
    }
    statusEl.textContent = results.length + " result" + (results.length === 1 ? "" : "s");
    for (var i = 0; i < results.length; i++) {
      var r = results[i];
      var li = document.createElement("li");
      li.setAttribute("role", "option");
      li.setAttribute("data-url", r.url);
      li.setAttribute("tabindex", "-1");
      li.innerHTML =
        '<span class="xd-sr-type xd-sr-type--' + escape(r.type) + '">' +
          escape(TYPE_LABELS[r.type] || r.type) +
        '</span>' +
        '<span class="xd-sr-title">' + escape(r.title) + '</span>' +
        '<span class="xd-sr-excerpt">' + escape(excerpt(r.body, tokens)) + '</span>';
      li.addEventListener("click", function () {
        window.location.href = this.getAttribute("data-url");
      });
      li.addEventListener("mouseenter", function () {
        setActive(Array.prototype.indexOf.call(resultsList.children, this));
      });
      resultsList.appendChild(li);
    }
  }

  // ── Keyboard navigation ──────────────────────────────────────────────────

  function setActive(idx) {
    var items = resultsList.children;
    for (var i = 0; i < items.length; i++) {
      items[i].classList.toggle("xd-sr-active", i === idx);
    }
    activeIdx = idx;
    if (idx >= 0 && items[idx]) {
      items[idx].scrollIntoView({ block: "nearest" });
    }
  }

  function onInputKey(e) {
    var items = resultsList.children;
    if (e.key === "Escape") { close(); return; }
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setActive(Math.min(activeIdx + 1, items.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setActive(Math.max(activeIdx - 1, 0));
    } else if (e.key === "Enter" && activeIdx >= 0 && items[activeIdx]) {
      window.location.href = items[activeIdx].getAttribute("data-url");
    }
  }

  // ── Input handler ────────────────────────────────────────────────────────

  var debounceTimer;
  function onInput() {
    var q = input.value.trim();
    clearTimeout(debounceTimer);
    if (!q) { resultsList.innerHTML = ""; statusEl.textContent = ""; return; }
    debounceTimer = setTimeout(function () {
      if (!indexData) {
        statusEl.textContent = "Loading\u2026";
        loadIndex().then(function () {
          var results = search(q);
          renderResults(results, tokenize(q));
        }).catch(function () {
          statusEl.textContent = "Search unavailable.";
        });
      } else {
        renderResults(search(q), tokenize(q));
      }
    }, 80);
  }

  // ── Open / close ─────────────────────────────────────────────────────────

  function open() {
    mount();
    overlay.classList.add("xd-search-open");
    document.body.style.overflow = "hidden";
    input.value = "";
    resultsList.innerHTML = "";
    statusEl.textContent = "";
    input.focus();
    // Pre-load index in background
    loadIndex().catch(function () {});
  }

  function close() {
    if (!overlay) return;
    overlay.classList.remove("xd-search-open");
    document.body.style.overflow = "";
  }

  // ── Global keyboard shortcut ─────────────────────────────────────────────

  document.addEventListener("keydown", function (e) {
    if ((e.metaKey || e.ctrlKey) && e.key === "k") {
      e.preventDefault();
      if (overlay && overlay.classList.contains("xd-search-open")) {
        close();
      } else {
        open();
      }
    }
    if (e.key === "Escape" && overlay && overlay.classList.contains("xd-search-open")) {
      close();
    }
  });

  // ── Public API (attached to window for the trigger button) ───────────────

  window.xdSearchOpen = open;
  window.xdSearchClose = close;
})();
